import { useCallback, useMemo } from 'react';

import BigNumber from 'bignumber.js';

import type { IStackProps } from '@onekeyhq/components';
import {
  Icon,
  NumberSizeableText,
  SizableText,
  Stack,
  XStack,
  YStack,
} from '@onekeyhq/components';
import { listItemPressStyle } from '@onekeyhq/shared/src/style';
import type { IMarketAccountPortfolioPnl } from '@onekeyhq/shared/types/marketV2';
import type { ISwapToken } from '@onekeyhq/shared/types/swap/types';

import { Currency, useCurrency } from '../../../components/Currency';
import { Token } from '../../../components/Token';
import { useNetworkLogoUri } from '../../../hooks/useNetworkLogoUri';

interface ISwapProPositionItemProps {
  token: ISwapToken;
  onPress: (token: ISwapToken) => void;
  disabled?: boolean;
  props?: IStackProps;
  pnl?: IMarketAccountPortfolioPnl;
  stockLayout?: boolean;
}

const SwapProPositionItem = ({
  token,
  onPress,
  disabled,
  props,
  pnl,
  stockLayout = false,
}: ISwapProPositionItemProps) => {
  const currencyInfo = useCurrency();

  const tokenNetworkImageUri = useNetworkLogoUri({
    logoUri: token.networkLogoURI,
    networkId: token.networkId,
  });

  const handlePress = useCallback(() => {
    if (!disabled) {
      onPress(token);
    }
  }, [disabled, onPress, token]);

  const pnlDisplay = useMemo(() => {
    if (!pnl?.isPnlSupported) return null;
    const unrealizedBN = new BigNumber(pnl.unrealizedPnlUsd);
    if (unrealizedBN.isNaN()) return null;

    const isPositive = unrealizedBN.gt(0);
    const isNegative = unrealizedBN.lt(0);

    let color = '$textSubdued';
    if (isPositive) color = '$textSuccess';
    if (isNegative) color = '$textCritical';

    let prefix = '';
    if (isPositive) prefix = '+';
    if (isNegative) prefix = '-';

    return {
      value: unrealizedBN.abs().toFixed(),
      percent: pnl.unrealizedPnlPercent,
      prefix,
      color,
    };
  }, [pnl]);

  return (
    <Stack
      flexDirection="row"
      alignItems="center"
      minHeight={stockLayout ? 56 : '$11'}
      h={stockLayout ? 56 : undefined}
      gap="$3"
      py={stockLayout ? '$0' : '$2'}
      px="$2"
      mx="$-2"
      borderRadius="$3"
      borderCurve="continuous"
      userSelect="none"
      onPress={handlePress}
      {...(disabled && { opacity: 0.5 })}
      {...(!disabled && listItemPressStyle)}
      {...props}
    >
      <XStack
        alignItems="center"
        gap={stockLayout ? '$3' : '$2'}
        flexGrow={1}
        flexBasis={0}
        alignSelf={stockLayout ? 'stretch' : undefined}
      >
        <Token
          size="md"
          tokenImageUri={token.logoURI}
          networkImageUri={tokenNetworkImageUri}
        />
        <YStack
          pt={stockLayout ? '$2' : undefined}
          gap={stockLayout ? 1 : undefined}
          alignSelf={stockLayout ? 'stretch' : undefined}
        >
          <XStack alignItems="center" gap="$0.5">
            <SizableText size="$bodyLgMedium">{token.symbol}</SizableText>
            {stockLayout ? null : (
              <Icon name="ChevronRightSmallOutline" size="$5" />
            )}
          </XStack>
          <NumberSizeableText
            size="$bodyMd"
            color="$textSubdued"
            formatter="balance"
            numberOfLines={1}
          >
            {token.balanceParsed}
          </NumberSizeableText>
        </YStack>
      </XStack>

      <YStack
        alignItems="flex-end"
        flexShrink={0}
        pt={stockLayout ? '$2' : undefined}
        gap={stockLayout ? '$1' : undefined}
        alignSelf={stockLayout ? 'stretch' : undefined}
      >
        <NumberSizeableText
          size="$bodyLgMedium"
          formatter="value"
          formatterOptions={{ currency: currencyInfo.symbol }}
          numberOfLines={1}
        >
          {token.fiatValue}
        </NumberSizeableText>
        {stockLayout && pnlDisplay ? (
          <NumberSizeableText
            size="$bodySm"
            color={pnlDisplay.color}
            formatter="priceChange"
            formatterOptions={{ showPlusMinusSigns: true }}
            numberOfLines={1}
          >
            {pnlDisplay.percent}
          </NumberSizeableText>
        ) : null}
        {!stockLayout && pnlDisplay ? (
          <XStack alignItems="center" justifyContent="flex-end" gap="$0.5">
            <XStack alignItems="center" gap="$0">
              {pnlDisplay.prefix ? (
                <SizableText
                  size="$bodyMd"
                  color={pnlDisplay.color}
                  numberOfLines={1}
                >
                  {pnlDisplay.prefix}
                </SizableText>
              ) : null}
              <Currency
                size="$bodyMd"
                color={pnlDisplay.color}
                formatter="value"
                sourceCurrency="usd"
                numberOfLines={1}
              >
                {pnlDisplay.value}
              </Currency>
            </XStack>
            <SizableText
              size="$bodyMd"
              color={pnlDisplay.color}
              numberOfLines={1}
            >
              {`(${pnlDisplay.percent}%)`}
            </SizableText>
          </XStack>
        ) : null}
      </YStack>
    </Stack>
  );
};

export default SwapProPositionItem;
